"""Existing authenticated LAN panel; explicit controls, observed state, no automatic opt-in."""
PAGE = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ричи · управление</title>
<style>
:root{color-scheme:dark;font:16px/1.5 system-ui,-apple-system,sans-serif;background:#101820;color:#edf4f7}*{box-sizing:border-box}body{margin:0;padding:24px}main{max-width:900px;margin:24px auto}header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}h1{font-size:32px;line-height:1.2;margin:0 0 6px}h2{font-size:21px;margin:0 0 12px}p{margin:8px 0 16px}.muted,small{color:#b6c7d0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#1b2a35;border:1px solid #344956;border-radius:20px;padding:24px}.wide{grid-column:1/-1}.buttons{display:flex;gap:10px}button,input{font:inherit;border:0;border-radius:12px;padding:13px 16px;min-height:48px}button{background:#8be0bc;color:#0d2b20;cursor:pointer;font-weight:650}button.secondary{background:#344956;color:#edf4f7}button.danger{background:#efb1a7;color:#451e1b}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible{outline:3px solid #e9cb70;outline-offset:3px}.buttons button{flex:1}input{width:100%;background:#101820;color:#fff;border:1px solid #526976}input[type=range]{padding:0;border:0;accent-color:#8be0bc;min-height:36px}.badge{padding:6px 12px;border-radius:30px;background:#344956;white-space:nowrap;font-size:14px}.good{color:#a2eac6}.bad{color:#ffc2b7}#notice{min-height:28px;margin:8px 0 18px}#updated{display:block;font-size:13px;margin-top:5px}#login{max-width:460px;margin:60px auto}#connect,#stop{width:100%;margin-top:12px}#stop{font-size:18px}#sharelink{margin-top:12px}footer{display:flex;gap:12px;justify-content:space-between;flex-wrap:wrap;margin:20px 0}footer button{font-size:14px}.detail{min-height:48px}.state{font-size:22px;font-weight:650;margin-bottom:4px}#login-error{min-height:25px}#volume-value{float:right}#volume-status{display:block;min-height:25px}#session-actions{margin-top:24px}#limits p{font-size:15px}#limits h2{font-size:18px}a{color:#a2eac6}@media(max-width:640px){body{padding:16px}main{margin:16px auto}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.card{padding:20px}header{align-items:flex-start}h1{font-size:28px}#connection{font-size:12px}.buttons{gap:8px}button{padding:12px}footer button{width:100%}}
</style></head><body><main>
<header><div><h1>Ричи</h1><div class="muted">Управление компаньоном</div></div><div><span id="connection" class="badge">Нет подключения</span><small id="updated">Состояние не получено</small></div></header>
<section id="login" class="card"><h2>Подключиться к Ричи</h2><p class="muted">Введите ключ доступа к локальному Hub.</p><label for="token">Ключ доступа</label><input id="token" type="password" autocomplete="off" spellcheck="false"><button id="connect">Подключиться</button><p class="muted">Или выберите локальный файл ключа:</p><label for="token-file">Файл ключа доступа</label><input id="token-file" type="file"><small>Файл читается в браузере. Его содержимое используется только как ключ доступа к этому Hub.</small><div id="login-error" class="bad" role="status" aria-live="polite"></div></section>
<div id="controls" hidden><div id="notice" role="status" aria-live="polite"></div><div class="grid">
<section class="card"><h2>Микрофон</h2><div id="mic-state" class="state">Проверяем…</div><p id="mic-detail" class="muted detail">Нужно получить состояние робота.</p><div class="buttons"><button id="mic-on" disabled>Включить</button><button id="mic-off" class="secondary" disabled>Выключить</button></div><p><small>Выключение останавливает захват звука и сохраняется после перезапуска.</small></p></section>
<section class="card"><h2>Самостоятельные вопросы</h2><div id="auto-state" class="state">Проверяем…</div><p id="auto-detail" class="muted detail">Состояние пока неизвестно.</p><div class="buttons"><button id="auto-on" disabled>Включить</button><button id="auto-off" class="secondary" disabled>Выключить</button></div><p><small>Не чаще раза в пять минут, после тишины. Включаются отдельно от микрофона.</small></p></section>
<section class="card wide"><h2>Режим разговора</h2><div id="mode-state" class="state">Проверяем…</div><p id="mode-detail" class="muted detail">Состояние режима пока неизвестно.</p><div class="buttons"><button id="mode-normal" disabled>Обычный</button><button id="mode-alice" class="secondary" disabled>Тест с Алисой</button></div><p><small>Применяется со следующей реплики и сохраняется после перезапуска. Не включает микрофон, вопросы или движение. Это выбор теста, а не распознавание собеседника.</small></p></section>
<section class="card wide"><h2>Остановить речь и вопросы</h2><p class="muted">Выключит микрофон, прервёт речь и отключит самостоятельные вопросы. Возобновление — только явным включением.</p><button id="stop" class="danger">СТОП</button><small id="stop-detail">Микрофон и вопросы останутся выключены после перезапуска. Камерой эта кнопка не управляет.</small></section>
<section class="card"><h2>Громкость</h2><label for="volume">Динамик <output id="volume-value">—</output></label><input id="volume" type="range" min="0" max="100" step="1" value="0" disabled><small id="volume-status" role="status" aria-live="polite"></small></section>
<section id="limits" class="card"><h2>Камера и движение</h2><p id="motion-state">Разрешение на движение: состояние неизвестно.</p><p class="muted">Включение движения пока недоступно.</p><p class="muted">Состояние камеры здесь не определяется; управление пока недоступно. Выключение микрофона и СТОП не подтверждают выключение камеры.</p></section>
</div><footer><button id="refresh" class="secondary">Обновить состояние</button><button id="share" class="secondary">Ссылка для телефона</button><button id="logout" class="secondary">Закрыть доступ на этом устройстве</button></footer><div id="share-box" hidden><small>Ссылка предоставляет доступ к управлению. Откройте её на телефоне в той же локальной сети.</small><input id="sharelink" readonly aria-label="Ссылка для телефона"></div></div>
</main><script>
let token='',state=null,busy=false,stopping=false,volumeBusy=false,volumeDragging=false,serial=0,refreshing=false;
const el=id=>document.getElementById(id);
try{const fragment=decodeURIComponent(location.hash.slice(1));token=fragment||sessionStorage.getItem('reachy-control-token')||'';if(fragment)sessionStorage.setItem('reachy-control-token',token)}catch(e){}
history.replaceState(null,'',location.pathname);
function show(){el('login').hidden=!!token;el('controls').hidden=!token;if(!token){el('connection').textContent='Нет подключения';el('connection').className='badge';el('updated').textContent='Состояние не получено'}}
async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:controller.signal});if(response.status===401){token='';state=null;try{sessionStorage.removeItem('reachy-control-token')}catch(e){}show();el('login-error').textContent='Неверный ключ доступа';throw Error('Неверный ключ доступа')}if(!response.ok){if(response.status===409)throw Error('Состояние изменилось или управление запрещено. Состояние будет обновлено.');throw Error('Нет связи с Hub или роботом. Действие не подтверждено.')}return await response.json()}catch(error){if(error.name==='AbortError')throw Error('Робот не подтвердил действие вовремя. Проверяем фактическое состояние.');throw error}finally{clearTimeout(timer)}}
function unavailable(message){state=null;el('connection').textContent='Нет связи';el('connection').className='badge bad';el('updated').textContent='Актуальное состояние неизвестно';el('mic-state').textContent='Неизвестно';el('mic-detail').textContent='Остановка захвата не подтверждена.';el('auto-state').textContent='Неизвестно';el('auto-detail').textContent='Состояние расписания не получено.';for(const id of ['mic-on','mic-off','auto-on','auto-off','mode-normal','mode-alice','volume'])el(id).disabled=true;el('mode-state').textContent='Неизвестно';el('mode-detail').textContent='Состояние режима не получено.';el('motion-state').textContent='Разрешение на движение: неизвестно.';el('notice').textContent=message;el('notice').className='bad';el('stop').disabled=stopping||!token}
function render(){el('stop').disabled=stopping||!token;if(!state)return;const m=state.microphone,a=state.automatic,p=state.policy,owned=p.microphone_owner_id!==null||p.motion_policy_owner_id!==null,safe=!owned&&!p.quiet&&!p.privacy_all&&!m.error;el('connection').textContent='На связи';el('connection').className='badge good';el('updated').textContent='Обновлено '+new Date().toLocaleTimeString('ru-RU');el('mic-state').textContent=m.error?'Ошибка состояния':m.closed?'Выключен':!m.enabled?'Останавливается…':m.capture_active?'Включён':'Включён · захват не активен';el('mic-state').className='state '+(m.enabled&&m.capture_active?'good':'');let detail=m.error?'Есть ошибка микрофона или сохранения настройки. Проверьте фактический захват; сохранение после перезапуска не подтверждено.':m.closed?'Захват звука остановлен.':m.capture_active?'Захват звука активен.':'Захват звука пока не подтверждён.';const phase={speaking:'Ричи отвечает.',processing:'Ричи обрабатывает речь.',listening:'Ричи ожидает речь.',paused:'Прослушивание приостановлено.',error:'Ошибка обработки звука.'}[state.phase];if(phase)detail+=' '+phase;if(owned)detail+=' Управление занято другим владельцем.';if(p.quiet||p.privacy_all)detail+=' Действует тихий режим или запрет доступа.';el('mic-detail').textContent=detail;el('mic-on').disabled=busy||stopping||!safe||(m.enabled&&m.listening);el('mic-off').disabled=busy||stopping||m.closed;el('auto-state').textContent=a.enabled?'Включены':a.requested?'Ожидают готовности':'Выключены';el('auto-detail').textContent=a.enabled?({RUNNING:'Ричи задаёт самостоятельный вопрос.',COOLDOWN:'Пауза до следующего вопроса.',WAITING_FOR_IDLE:'Ожидают тишины и свободного разговора.'}[a.state]||'Расписание включено.'):a.requested?'Постоянное разрешение сохранено, активное расписание сейчас выключено.':'Самостоятельные вопросы не запускаются.';el('auto-on').disabled=busy||stopping||!safe||!m.enabled||!m.listening||!m.capture_active||state.phase!=='listening'||a.enabled;el('auto-off').disabled=busy||stopping||(!a.enabled&&!a.requested);const c=state.conversation_mode;el('mode-state').textContent=c.error?'Ошибка настройки':c.mode==='alice_test'?'Тест с Алисой':'Обычный';el('mode-detail').textContent=c.error?'Настройка не прочитана или не сохранена. Выберите режим повторно.':c.mode==='alice_test'?'Ответы обращены к Алисе; включён тестовый контекст.':'Без тестового обращения и контекста Алисы.';for(const [id,mode] of [['mode-normal','normal'],['mode-alice','alice_test']]){el(id).disabled=busy||stopping||!safe||(!c.error&&c.mode===mode);el(id).setAttribute('aria-pressed',String(c.mode===mode&&!c.error))}el('stop').disabled=stopping||!token;el('motion-state').textContent='Разрешение на движение: '+(p.motor_enabled?'включено; включение из панели недоступно.':'выключено.');if(!volumeBusy&&!volumeDragging&&Number.isInteger(state.volume.percent)){el('volume').value=state.volume.percent;el('volume-value').textContent=state.volume.percent+'%'}el('volume').disabled=busy||stopping||volumeBusy||!state.volume.enabled}
async function refresh(){if(!token||refreshing||busy||stopping)return;refreshing=true;const revision=serial;try{const value=await api('/control/panel-state');if(revision!==serial)return;if(value.version!==1||!value.binding||!value.microphone||!value.automatic||!value.policy||!value.volume||!value.conversation_mode||!['normal','alice_test'].includes(value.conversation_mode.mode))throw Error('Эта версия панели не поддерживается роботом.');state=value;if(el('notice').className==='bad'){el('notice').textContent='';el('notice').className=''}render()}catch(error){if(revision===serial)unavailable(error.message)}finally{refreshing=false}}
async function command(action){const isStop=action==='stop';if(!token||(isStop?stopping:busy||stopping))return;const positive=action==='microphone_on'||action==='automatic_on',modeAction=action==='mode_normal'||action==='mode_alice_test';if((positive||modeAction)&&!state)return;const body=modeAction?{action,binding:state.binding,mode_generation:state.conversation_mode.generation}:positive?{action,binding:state.binding}:{action};const revision=++serial;if(isStop)stopping=true;else busy=true;el('notice').textContent=isStop?'Останавливаем…':'Применяем…';el('notice').className='muted';render();try{const result=await api('/control/panel',body);if(revision!==serial)return;if(result.accepted!==true||result.action!==action||!result.state)throw Error('Действие не подтверждено роботом.');state=result.state;el('notice').textContent=(action==='stop'||action==='microphone_off')?(state.microphone.closed?'Захват звука остановлен.':'Команда принята; остановка захвата ещё не подтверждена.'):'Состояние обновлено.';el('notice').className='';render()}catch(error){if(revision===serial)unavailable(error.message)}finally{if(isStop)stopping=false;if(revision===serial){busy=false;render();refresh()}}}
function loginWithToken(value){token=value.trim();if(!token)return;try{sessionStorage.setItem('reachy-control-token',token)}catch(e){}el('token').value='';show();el('login-error').textContent='';refresh()}
el('connect').onclick=()=>loginWithToken(el('token').value);
el('token-file').onchange=()=>{const file=el('token-file').files[0];if(!file)return;if(file.size<1||file.size>4096){el('login-error').textContent='Нужен небольшой файл ключа доступа.';el('token-file').value='';return}const reader=new FileReader();reader.onload=()=>{const value=String(reader.result).trim();el('token-file').value='';if(!/^[\x21-\x7e]{16,2048}$/.test(value)){el('login-error').textContent='Файл не похож на ключ доступа.';return}loginWithToken(value)};reader.onerror=()=>{el('token-file').value='';el('login-error').textContent='Не удалось прочитать файл ключа.'};reader.readAsText(file)};
el('token').onkeydown=event=>{if(event.key==='Enter')el('connect').click()};
for(const [id,action] of [['mic-on','microphone_on'],['mic-off','microphone_off'],['auto-on','automatic_on'],['auto-off','automatic_off'],['stop','stop'],['mode-normal','mode_normal'],['mode-alice','mode_alice_test']])el(id).onclick=()=>command(action);
el('refresh').onclick=()=>refresh();el('share').onclick=()=>{el('share-box').hidden=false;el('sharelink').value=location.origin+'/control#'+encodeURIComponent(token);el('sharelink').select()};
el('logout').onclick=()=>{++serial;token='';state=null;busy=false;stopping=false;volumeBusy=false;volumeDragging=false;el('sharelink').value='';el('share-box').hidden=true;try{sessionStorage.removeItem('reachy-control-token')}catch(e){}show()};
el('volume').oninput=()=>{volumeDragging=true;el('volume-value').textContent=el('volume').value+'%'};
el('volume').onchange=async()=>{volumeDragging=false;if(volumeBusy||!state||busy||stopping)return;volumeBusy=true;render();el('volume-status').textContent='Применяем…';try{await api('/control/volume',{volume_percent:Number(el('volume').value)});el('volume-status').textContent='Громкость сохранена.'}catch(error){el('volume-status').textContent=error.message}finally{volumeBusy=false;render();refresh()}};
show();refresh();setInterval(refresh,2000);
</script></body></html>'''
